<div class="page-heading"><h1>Kehadiran Saya</h1><p>Catatan kehadiran pribadi. Gunakan kode atau pindai QR yang dibagikan admin saat presensi dibuka.</p></div>
<?php $checkin=(int)query('session');if($checkin):authorizedBatch($uid,(int)(one('SELECT batch_id FROM training_sessions WHERE id=?',[$checkin])['batch_id']??0)); ?><section class="panel"><h2>Konfirmasi presensi</h2><form class="portal-form" method="post" data-busy-form><?= actionFields('checkin',$checkin) ?><label>Kode presensi<input name="token" required value="<?= e(query('token')) ?>" maxlength="128"></label><button class="btn" type="submit">Catat kehadiran saya</button></form></section><?php endif; ?>
<?php $attendance=rows("SELECT s.*,a.status,a.checked_in_at,p.title program_title FROM training_sessions s JOIN registrations r ON r.batch_id=s.batch_id JOIN enrollments en ON en.registration_id=r.id JOIN training_batches b ON b.id=s.batch_id JOIN training_programs p ON p.slug=b.program_slug LEFT JOIN attendance_records a ON a.session_id=s.id AND a.user_id=r.user_id WHERE r.user_id=? AND r.status='approved' AND en.status IN ('active','completed') ORDER BY s.starts_at DESC",[$uid]);if(!$attendance)emptyState('Belum ada catatan kehadiran','Kehadiran akan muncul bersama sesi pelatihan yang telah diterbitkan.','portal.php?view=schedule','Lihat jadwal'); ?>
<div class="stack" style="margin-top:20px"><?php foreach($attendance as $record): ?><article class="panel"><div class="row"><h2><?= e($record['title']) ?></h2><span class="badge <?= e($record['status']) ?>"><?= e($record['status']?statusText($record['status']):'Belum tercatat') ?></span></div><p class="muted"><?= e($record['program_title'].' · '.$record['starts_at']) ?></p><p class="muted">Waktu presensi: <?= e($record['checked_in_at']?:'—') ?></p><?php if(!$record['status']&&$record['attendance_token_hash']&&$record['attendance_open_at']&&$record['attendance_close_at']&&strtotime($record['attendance_open_at'])<=time()&&strtotime($record['attendance_close_at'])>=time()): ?><div class="actions"><a class="btn secondary" href="portal.php?view=attendance&amp;session=<?= (int)$record['id'] ?>">Masukkan kode presensi</a></div><?php endif; ?></article><?php endforeach; ?></div>
